document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{document.querySelector('#dialog-title').textContent=b.dataset.evidence;document.querySelector('#dialog-body').innerHTML='<p>11-05 15:20 · 打开实验工作区</p><p>11-05 15:36 · 运行训练代码，损失 0.024</p><p>11-05 15:48 · 保存训练结果</p><small>示例过程记录</small>';document.querySelector('#dialog').showModal()});
document.querySelector('#read-all')?.addEventListener('click',e=>{e.target.textContent='全部已读';e.target.disabled=true});
document.querySelector('#run')?.addEventListener('click',()=>document.querySelector('#terminal').textContent='演示输出（未执行编辑器代码）\nweight: 2.0\n进程结束 · exit 0');

if(page==='report'){const fields=['process','analysis','conclusion'];const draft=JSON.parse(localStorage.getItem('teacher-report-draft')||'{}');fields.forEach(k=>document.getElementById(k).value=draft[k]||'');const save=()=>{localStorage.setItem('teacher-report-draft',JSON.stringify(Object.fromEntries(fields.map(k=>[k,document.getElementById(k).value]))));document.querySelector('#report-state').textContent='草稿已保存到当前浏览器'};document.querySelector('#save-report').onclick=save;document.querySelector('#report-form').onsubmit=e=>{e.preventDefault();save();document.querySelector('#report-state').textContent='验证报告提交成功（演示）· 未写入学生成绩或教学统计';toast('验证流程完成')}}
if(page==='review'){
const names=['林雨桐','陈思远','周明轩','李若溪','张子涵','刘浩然','赵嘉宁','孙语晨','吴思齐','郑一诺','许知远','何沐阳'];const records=names.map((name,i)=>({id:i,name,number:'2024010'+String(21+i).padStart(2,'0'),ai:null,score:null,confirmed:false}));const selected=new Set();let current=0;const filtered=()=>records.filter(r=>(r.name.includes(document.querySelector('#review-search').value)||r.number.includes(document.querySelector('#review-search').value))&&(document.querySelector('#review-filter').value==='all'||(document.querySelector('#review-filter').value==='confirmed')===r.confirmed));
function render(){const rows=filtered();current=Math.min(current,Math.max(0,Math.ceil(rows.length/5)-1));document.querySelector('#result-count').textContent=`共 ${rows.length} 份报告`;document.querySelector('#selection').textContent=`已选择 ${selected.size} 份`;document.querySelector('#page-count').textContent=`${current+1} / ${Math.max(1,Math.ceil(rows.length/5))}`;document.querySelector('#select-all').checked=rows.length>0&&rows.every(r=>selected.has(r.id));document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=(current+1)*5>=rows.length;document.querySelector('#review-table').innerHTML=table(['选择','学生 / 学号','AI 建议','教师分数','状态'],rows.slice(current*5,current*5+5).map(r=>[`<input type="checkbox" aria-label="选择${r.name}" data-id="${r.id}" ${selected.has(r.id)?'checked':''}>`,`${r.name}<br><small>${r.number}</small>`,r.ai??'尚未评分',`<input class="score" type="number" min="0" max="100" aria-label="${r.name}教师分数" data-score="${r.id}" value="${r.score??''}" ${r.confirmed?'disabled':''}>`,r.confirmed?'已确认':'待确认']));document.querySelectorAll('[data-id]').forEach(c=>c.onchange=()=>{c.checked?selected.add(+c.dataset.id):selected.delete(+c.dataset.id);render()});document.querySelectorAll('[data-score]').forEach(c=>c.onchange=()=>{records[+c.dataset.score].score=c.value===''?null:+c.value});}
document.querySelector('#select-all').onchange=e=>{filtered().forEach(r=>e.target.checked?selected.add(r.id):selected.delete(r.id));render()};['review-search','review-filter'].forEach(id=>document.getElementById(id).oninput=()=>{current=0;selected.clear();render()});document.querySelector('#prev').onclick=()=>{current--;render()};document.querySelector('#next').onclick=()=>{current++;render()};
document.querySelector('#ai').onclick=()=>{let n=0;records.filter(r=>selected.has(r.id)&&!r.confirmed).forEach(r=>{r.ai=82+r.id%13;n++});document.querySelector('#batch-status').textContent=`已生成 ${n} 份 AI 建议（演示），待教师采纳与确认`;render()};document.querySelector('#adopt').onclick=()=>{let n=0;records.filter(r=>selected.has(r.id)&&r.ai!==null&&!r.confirmed).forEach(r=>{r.score=r.ai;n++});render();toast(`已采纳 ${n} 份建议，尚未确认成绩`)};document.querySelector('#confirm').onclick=()=>{const eligible=records.filter(r=>selected.has(r.id)&&!r.confirmed&&r.score!==null&&Number.isFinite(r.score)&&r.score>=0&&r.score<=100);if(!eligible.length)return toast('请先选择报告并填写 0–100 的有效分数');document.querySelector('#dialog-title').textContent='确认教师成绩';document.querySelector('#dialog-body').innerHTML=`<p>将确认 ${eligible.length} 份报告的教师分数。无有效分数和已确认报告将跳过。</p><button class="primary" id="final-confirm">确认这 ${eligible.length} 份成绩</button>`;document.querySelector('#dialog').showModal();document.querySelector('#final-confirm').onclick=()=>{eligible.forEach(r=>r.confirmed=true);document.querySelector('#dialog').close();render();toast(`已确认 ${eligible.length} 份成绩（演示）`)}};render();
}

if(['workbench','report'].includes(page)){const experiment=new URLSearchParams(location.search).get('experiment')||'线性回归与梯度下降';document.querySelector('.note').textContent=`教师验证模式 · 机器学习基础 / ${experiment} · 不计入正式任务与成绩`;document.querySelectorAll('a[href="report.html"],a[href="workbench.html"]').forEach(a=>a.href=a.getAttribute('href')+'?experiment='+encodeURIComponent(experiment));}
